package com.sanasboutique.backend.catalog.dto.request;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.math.BigDecimal;

/**
 * itemCode is deliberately absent - it's generated by the backend, never
 * user-entered (see ServiceItem's class doc). Images are uploaded
 * separately, one multipart request per file, once the item exists - see
 * CatalogController's image endpoints.
 */
public record ServiceItemRequest(
        @NotBlank(message = "Name is required") @Size(max = 150, message = "At most 150 characters")
                String name,
        @Size(max = 255, message = "At most 255 characters") String description,
        @NotNull(message = "Price is required")
                @DecimalMin(value = "0.0", inclusive = true, message = "Price cannot be negative")
                BigDecimal price,
        @Min(value = 0, message = "Quantity cannot be negative") Integer quantity,
        // Optional "Value if lost" of one piece (jewellery rental); pre-fills the missing charge at return.
        @DecimalMin(value = "0.0", inclusive = true, message = "Value cannot be negative")
                BigDecimal replacementValue) {}
